import type { PitchLocation, PitchProfile } from "../timing/Timeline.ts";
import type { SwingJudgment } from "../timing/SwingJudge.ts";
import type { GameSnapshot, PlateOutcome, PlayReport } from "../game/GameState.ts";
import { formatCount, formatScore, formatScoreline } from "../game/GameState.ts";
import { formatBases } from "../game/Baserunners.ts";
import { describeLocation, type Rng } from "../game/PitchSelector.ts";
import { describeField, excitementFor, type PlayResult } from "../game/OutcomeResolver.ts";
import { isHighLeverage } from "../game/Leverage.ts";
import type { Phrase, Speaker } from "./VoiceBackend.ts";

/**
 * Modular commentary assembly.
 *
 * The brief's pattern is [Pitcher_Action] + [Pitch_Type_Detail] + [Result_Call],
 * and that is what gets built here — but split across two deliveries rather than
 * one, because that is how the fragments actually fall in a broadcast:
 *
 *   at release   "Smyth fires..."                                    <- action
 *   after the play  "...a 94 mile an hour fastball, called strike     <- detail + result
 *                    three on the outside corner!"
 *
 * Splitting there is not cosmetic. Naming the pitch type before it arrives would
 * hand the batter the answer while the ball is still in the air, and the whole
 * game is about reading the pitch from the sound of it.
 *
 * Beyond the pitch-by-pitch pair: situation lines, inning breaks, game-overs,
 * score clauses on runs, and between-pitch bridge fill (count, chess, atmosphere)
 * so the booth sounds like a real radio broadcast in the gaps.
 */

export interface NarrationContext {
  pitcher: string;
  batter: string;
  /** Hand used this AB (switch resolved vs pitcher). */
  batterHand?: "L" | "R";
  homeTeamName: string;
  awayTeamName: string;
  profile: PitchProfile;
  location: PitchLocation;
  judgment: SwingJudgment;
  result: PlayResult;
  outcome: PlateOutcome;
  report: PlayReport;
  after: GameSnapshot;
  countBefore: { balls: number; strikes: number };
  countAfter: { balls: number; strikes: number };
  /** -1 pulled to +1 opposite field. */
  spray: number;
  leverage: number;
  rng: Rng;
}

// --- [Pitcher_Action] ------------------------------------------------------

const PITCHER_ACTION: readonly string[] = [
  "{pitcher} fires.",
  "{pitcher} deals.",
  "Here's the pitch.",
  "{pitcher} comes set... and delivers.",
  "The wind-up, and the pitch.",
  "{pitcher} rocks and fires.",
];

// --- [Pitch_Type_Detail] ---------------------------------------------------

const PITCH_DETAIL: readonly string[] = [
  "A {velocity} mile an hour {label},",
  "That's the {label}, {velocity},",
  "{label} at {velocity},",
  "He goes to the {label},",
];

/**
 * Said as the ball leaves the hand. Takes only the pitcher's name, because at this
 * point in the pitch nothing else has happened yet — and deliberately says nothing
 * about pitch type or location.
 */
export function buildDeliveryCall(pitcher: string, rng: Rng): Phrase {
  const index = pickIndex(rng, PITCHER_ACTION.length);
  const template = PITCHER_ACTION[index] as string;
  return {
    id: `action.${index}`,
    text: template.replace("{pitcher}", pitcher),
    speaker: "announcer",
    energy: 0.35,
  };
}

export function buildResultCall(ctx: NarrationContext): Phrase {
  const detailIndex = pickIndex(ctx.rng, PITCH_DETAIL.length);
  const detail = (PITCH_DETAIL[detailIndex] as string)
    .replace("{velocity}", String(ctx.profile.velocityMph))
    .replace(/\{label\}/g, ctx.profile.label);

  const call = resultCall(ctx);
  const score = scoreClause(ctx);
  const text = score ? `${detail} ${call.text} ${score}` : `${detail} ${call.text}`;

  const energy = clamp01((excitementFor(ctx.result) - 1) / 4 + (ctx.report.runsScored > 0 ? 0.15 : 0));

  return {
    id: score ? `detail.${detailIndex}+${call.id}+score` : `detail.${detailIndex}+${call.id}`,
    text,
    speaker: "announcer",
    energy,
  };
}

/**
 * Appended to any result call that put a run across — a home run, a bloop single
 * with a runner on third, a sacrifice fly, a bases-loaded walk. Broadcasters
 * follow almost every scoring play with the new score, so this fires purely off
 * `report.runsScored` rather than being threaded through each individual case in
 * `resultCall`, and applies uniformly across hits, outs, and walks alike.
 */
function scoreClause(ctx: NarrationContext): string | null {
  if (ctx.report.runsScored <= 0) return null;
  const runWord = ctx.report.runsScored === 1 ? "run" : "runs";
  const scoreText = formatScore(ctx.after.score, ctx.homeTeamName, ctx.awayTeamName);
  return `That's ${ctx.report.runsScored} ${runWord} in — ${capitalize(scoreText)}.`;
}

// --- [Result_Call] ---------------------------------------------------------

interface CallFragment {
  id: string;
  text: string;
}

function resultCall(ctx: NarrationContext): CallFragment {
  const loc = describeLocation(ctx.location);
  const field = describeField(ctx.spray, ctx.batterHand ?? "R");
  const strikeout = ctx.outcome.kind === "strikeout";
  const walk = ctx.outcome.kind === "walk";
  const scored = ctx.report.runsScored > 0;

  switch (ctx.result) {
    case "called-strike":
      return strikeout
        ? choose(ctx.rng, "call.k-looking", [
            `called strike three, ${loc}! He's out looking.`,
            `and he's frozen! Strike three ${loc}, ${ctx.batter} never moved.`,
          ])
        : choose(ctx.rng, "call.strike-looking", [
            `called strike ${ordinalStrike(ctx.countAfter.strikes)}, ${loc}.`,
            `he takes it — strike ${ordinalStrike(ctx.countAfter.strikes)}, ${loc}.`,
            `over the plate for strike ${ordinalStrike(ctx.countAfter.strikes)}.`,
          ]);

    case "ball":
      if (walk && scored) {
        return choose(ctx.rng, "call.walk.forced-in", [
          `ball four — and with the bases loaded, that forces one home!`,
          `walks him, and with the bases juiced, the run scores on the force!`,
        ]);
      }
      return walk
        ? choose(ctx.rng, "call.walk", [
            `${loc} — ball four. ${ctx.batter} drops the bat and takes his base.`,
            `that's ball four, and he'll walk down to first.`,
          ])
        : choose(ctx.rng, "call.ball", [
            `${loc} — ball ${ctx.countAfter.balls}.`,
            `he lays off, ${loc}. Ball ${ctx.countAfter.balls}.`,
            `no chase there. Ball ${ctx.countAfter.balls}, ${loc}.`,
          ]);

    case "swinging-strike":
      return strikeout
        ? choose(ctx.rng, "call.k-swinging", [
            `he swings through it! Strike three, and ${ctx.batter} is gone.`,
            `swing and a miss — that's the punchout!`,
          ])
        : choose(ctx.rng, "call.whiff", [
            `swung on and missed. Strike ${ordinalStrike(ctx.countAfter.strikes)}.`,
            `he waves at it — strike ${ordinalStrike(ctx.countAfter.strikes)}.`,
          ]);

    case "foul-ball":
      return choose(ctx.rng, "call.foul", [
        `fouled straight back to the screen.`,
        `he gets a piece of it, and it's off into the netting.`,
        `fouled away, and we'll do it again.`,
      ]);

    case "home-run":
      return choose(ctx.rng, "call.homer", [
        `${ctx.batter} CRUSHES it — high, deep, and GONE, ${field}!`,
        `he got every bit of that one! Say goodbye — it is out of here, ${field}!`,
      ]);

    case "double":
      return choose(ctx.rng, "call.double", [
        `laced ${field} — into the gap, and ${ctx.batter} pulls in standing with a double!`,
        `off the wall ${field}! He'll have two.`,
      ]);

    case "single":
      return choose(ctx.rng, "call.single", [
        `a base hit ${field}, and ${ctx.batter} is aboard.`,
        `lined ${field} for a base knock.`,
      ]);

    case "line-out":
      if (ctx.report.note === "double-play") {
        return choose(ctx.rng, "call.lineout.dp", [
          `lined right at the fielder — and he doubles him off! Two outs on the play.`,
          `a scorching liner, caught, and the runner can't get back — twin killing!`,
        ]);
      }
      return choose(ctx.rng, "call.lineout", [
        `smoked ${field} — but right at somebody. He's out.`,
        `scorched, and caught. Nothing to show for it.`,
      ]);

    case "fly-out":
      if (ctx.report.note === "sac-fly") {
        return choose(ctx.rng, "call.flyout.sac", [
          `lifted deep enough ${field} — the runner tags and comes home after the catch!`,
          `a fly ball ${field}, caught, and the sacrifice does its job — here comes the run.`,
        ]);
      }
      return choose(ctx.rng, "call.flyout", [
        `a high fly ball ${field}... they camp under it, and squeeze it.`,
        `lifted ${field}, and that one is caught.`,
      ]);

    case "ground-out":
      if (ctx.report.note === "double-play") {
        return choose(ctx.rng, "call.groundout.dp", [
          `hit on the ground — turned into a double play! Two away, just like that.`,
          `chopped to the infield, around the horn for two! That costs them a runner.`,
        ]);
      }
      if (ctx.report.note === "productive-out") {
        return choose(ctx.rng, "call.groundout.productive", [
          `grounded to the right side — he's out at first, but that moves the run in from third!`,
          `chopped into the infield, and while he's retired, the run scores on the play.`,
        ]);
      }
      return choose(ctx.rng, "call.groundout", [
        `chopped into the infield — the throw across, and they get him.`,
        `grounded ${field}, and it's a routine play.`,
      ]);

    case "pop-up":
      return choose(ctx.rng, "call.popup", [
        `popped straight up. The catcher tosses the mask, and that's an easy out.`,
        `popped it up harmlessly into the infield.`,
      ]);
  }
}

// --- Situation, inning-break, and game-over calls ---------------------------

/**
 * Said once at the start of a plate appearance, gated on the count reading 0-0 —
 * the one moment that is guaranteed to occur exactly once per batter, since
 * `GameState` resets the count at that boundary and nowhere else.
 *
 * Deliberately not exhaustive about every situation on every batter; a broadcast
 * that describes the count and bases before literally every hitter grinds the
 * booth into white noise. This says the most whenever there is the most to say —
 * a fresh inning, real leverage, runners on — and stays quiet a fair amount of
 * the rest of the time.
 */
export function buildSituationLine(
  snapshot: GameSnapshot,
  leverage: number,
  homeTeamName: string,
  awayTeamName: string,
  rng: Rng,
): Phrase | null {
  const basesEmpty = !snapshot.bases.first && !snapshot.bases.second && !snapshot.bases.third;
  const isInningStart = snapshot.outs === 0 && basesEmpty;
  const bases = formatBases(snapshot.bases);
  const outsWord = snapshot.outs === 0 ? "nobody out" : snapshot.outs === 1 ? "one out" : "two out";

  if (isInningStart) {
    const half = snapshot.half === "top" ? "Top" : "Bottom";
    const scoreText = capitalize(formatScore(snapshot.score, homeTeamName, awayTeamName));
    return line(rng, "situation.inning-start", [
      `${half} of the ${ordinalInning(snapshot.inning)}. ${scoreText}. ${snapshot.batter} steps in for the ${snapshot.battingTeam}.`,
      `We move to the ${half.toLowerCase()} of the ${ordinalInning(snapshot.inning)}, ${scoreText}. ${snapshot.batter} digs in.`,
    ]);
  }

  if (isHighLeverage(leverage)) {
    return line(rng, "situation.high-leverage", [
      `${capitalize(bases)}, ${outsWord}. Real pressure moment here for ${snapshot.batter}.`,
      `${snapshot.batter} steps in with ${bases}, ${outsWord}. This is the moment.`,
    ]);
  }

  if (!basesEmpty) {
    return line(rng, "situation.runners", [
      `${capitalize(bases)}, ${outsWord}, as ${snapshot.batter} comes to the plate.`,
      `${snapshot.batter} up now. ${capitalize(bases)}, ${outsWord}.`,
    ]);
  }

  // Bases empty, mid-inning — still introduce the hitter; radio rarely stays mute
  // when a new batter digs in.
  return line(rng, "situation.plain", [
    `${snapshot.batter} steps in. ${outsWord}.`,
    `Here's ${snapshot.batter}. ${capitalize(outsWord)}.`,
    `${snapshot.batter} to the plate now for the ${snapshot.battingTeam}.`,
  ]);
}

/**
 * Between-pitch bridge — the air a radio booth fills while the catcher throws
 * it back and the pitcher takes a sign.
 *
 * Mid at-bat this almost always restates the count (the one thing a listener
 * tuning in mid-game needs), then layers situation and colour when there's room.
 * After a plate appearance it sets up the next hitter / the chess of the inning.
 */
export function buildBetweenPitchFill(ctx: NarrationContext): Phrase[] {
  const phrases: Phrase[] = [];
  const midAtBat = ctx.outcome.kind === "pitch";
  const after = ctx.after;
  const bases = formatBases(after.bases);
  const outsWord = after.outs === 0 ? "nobody out" : after.outs === 1 ? "one out" : "two out";
  const scoreText = capitalize(formatScore(after.score, ctx.homeTeamName, ctx.awayTeamName));

  if (midAtBat) {
    phrases.push(countRestate(ctx));

    if (ctx.rng() < 0.55 || isHighLeverage(ctx.leverage)) {
      phrases.push(
        line(ctx.rng, "bridge.situation", [
          `${capitalize(bases)}, ${outsWord}.`,
          `${scoreText}. ${capitalize(bases)}.`,
          `${outsWord}, ${bases}, and the count is ${speakCount(ctx.countAfter.balls, ctx.countAfter.strikes)}.`,
        ]),
      );
    }

    if (ctx.rng() < 0.7) {
      phrases.push(countChess(ctx));
    }

    if (ctx.rng() < 0.45) {
      phrases.push(
        color(ctx, "bridge.color", [
          `${ctx.pitcher} taking his time, looking in for the sign.`,
          `You can see ${ctx.batter} stepping out, adjusting the gloves.`,
          `Crowd's into every pitch in this at-bat.`,
          `${ctx.pitcher} has been mixing speeds — keep an ear on the flight.`,
          `Big part of hitting is knowing when to expand the zone, and when not to.`,
        ]),
      );
    }
  } else if (!ctx.report.gameEnded && !ctx.report.inningEnded) {
    // Plate appearance just ended; next batter isn't in yet, so paint the inning.
    phrases.push(
      line(ctx.rng, "bridge.pa-over", [
        `${scoreText}, ${outsWord}, ${bases}.`,
        `So it's ${scoreText} with ${outsWord}.`,
        `${capitalize(bases)}, ${outsWord}, as we get the next hitter.`,
      ]),
    );

    if (ctx.rng() < 0.6) {
      phrases.push(
        color(ctx, "bridge.pa-color", [
          `That changes the complexion of the inning a little.`,
          `${ctx.pitcher} will like getting that one behind him.`,
          `We'll see who the ${after.battingTeam} send up next.`,
          `Defense stays alert here — one swing can open this up.`,
        ]),
      );
    }
  }

  return phrases;
}

function countRestate(ctx: NarrationContext): Phrase {
  const { balls, strikes } = ctx.countAfter;
  const spoken = speakCount(balls, strikes);
  return line(ctx.rng, "bridge.count", [
    `And the count goes to ${spoken} on ${ctx.batter}.`,
    `So it's ${spoken}.`,
    `Count is ${spoken} now.`,
    `${spoken} the count.`,
    `That makes it ${formatCount(balls, strikes)} on ${ctx.batter}.`,
  ]);
}

function countChess(ctx: NarrationContext): Phrase {
  const { balls, strikes } = ctx.countAfter;
  const ahead = strikes > balls;
  const behind = balls > strikes;

  if (strikes === 2 && balls < 3) {
    return line(ctx.rng, "bridge.chess.two-strikes", [
      `Two strikes on ${ctx.batter} — ${ctx.pitcher} can expand the zone here.`,
      `He's in the driver's seat at two strikes. Something off-speed wouldn't surprise.`,
      `With two strikes, ${ctx.batter} has to protect. Tough spot.`,
    ]);
  }
  if (balls === 3 && strikes < 2) {
    return line(ctx.rng, "bridge.chess.full-or-three", [
      `Three balls — ${ctx.pitcher} has to come in and throw a strike.`,
      `Can't afford to free-pass him here. Got to challenge him.`,
      `Three-ball count. The zone gets a little smaller for the pitcher.`,
    ]);
  }
  if (balls === 3 && strikes === 2) {
    return line(ctx.rng, "bridge.chess.full", [
      `Full count. Everybody's moving, and anything near the zone gets protected.`,
      `Three and two. A lot riding on this next pitch.`,
    ]);
  }
  if (ahead) {
    return line(ctx.rng, "bridge.chess.ahead", [
      `${ctx.pitcher} ahead in the count — he can afford to nick a corner.`,
      `Pitcher's count. Expect him to work the edges.`,
    ]);
  }
  if (behind) {
    return line(ctx.rng, "bridge.chess.behind", [
      `${ctx.pitcher} behind now — likely a fastball to get back in it.`,
      `Hitter's count. ${ctx.batter} can look for something to drive.`,
    ]);
  }
  return line(ctx.rng, "bridge.chess.even", [
    `Even count. Chess match here between ${ctx.pitcher} and ${ctx.batter}.`,
    `Even count — both guys still hunting their pitch.`,
  ]);
}

/** "two and one", "oh and two", "three and two" — how radio says the count. */
function speakCount(balls: number, strikes: number): string {
  const b = balls === 0 ? "oh" : wordNumber(balls);
  const s = strikes === 0 ? "oh" : wordNumber(strikes);
  return `${b} and ${s}`;
}

function wordNumber(n: number): string {
  return n === 1 ? "one" : n === 2 ? "two" : n === 3 ? "three" : String(n);
}

/**
 * Said once a half-inning ends without the game itself ending. `before` is the
 * snapshot taken at the top of this pitch — the half and inning that *just*
 * ended — since `GameState` has already rolled over by the time `after` is read.
 */
export function buildInningBreakCall(
  before: GameSnapshot,
  after: GameSnapshot,
  homeTeamName: string,
  awayTeamName: string,
  rng: Rng,
): Phrase {
  const scoreText = capitalize(formatScore(after.score, homeTeamName, awayTeamName));
  const next =
    after.half === "top"
      ? `top of the ${ordinalInning(after.inning)}`
      : `bottom of the ${ordinalInning(after.inning)}`;

  return line(
    rng,
    "inning-break",
    [
      `That'll do it for the ${before.half} of the ${ordinalInning(before.inning)}. ${scoreText}, as we head to the ${next}.`,
      `Three outs. ${scoreText} heading to the ${next}.`,
    ],
    "announcer",
    0.3,
  );
}

/** Said once, when a play ends the game — by regulation or by walk-off. */
export function buildGameOverCall(
  report: PlayReport,
  after: GameSnapshot,
  batter: string,
  homeTeamName: string,
  awayTeamName: string,
  rng: Rng,
): Phrase {
  const winner = after.score.home > after.score.away ? homeTeamName : awayTeamName;
  const scoreline = formatScoreline(after.score);

  if (report.walkOff) {
    return line(
      rng,
      "gameover.walkoff",
      [
        `${batter.toUpperCase()} WINS IT! The ${winner} walk it off — final score ${scoreline}!`,
        `IT'S OVER! ${batter} delivers, and the ${winner} mob him at the plate — final, ${scoreline}!`,
      ],
      "announcer",
      1.0,
    );
  }

  return line(
    rng,
    "gameover.final",
    [
      `Ballgame! Final score: the ${winner} win it, ${scoreline}.`,
      `That'll do it — the ${winner} take this one, final score ${scoreline}.`,
    ],
    "announcer",
    0.85,
  );
}

// --- Colour commentary -----------------------------------------------------

/**
 * The colour man only speaks when he has something to say and there is room to say
 * it. He is priority 2 in the queue, so the next pitch cuts him off mid-sentence —
 * which is exactly what happens on a real broadcast.
 */
export function buildColorLine(ctx: NarrationContext): Phrase | null {
  const j = ctx.judgment;

  if (j.swung && j.plateCoverage < 0.35) {
    return color(ctx, "color.chase", [
      `He chased that one. That was nowhere near the plate.`,
      `You can't offer at that. It's a ball in any ballpark.`,
    ]);
  }
  if (j.swung && j.deltaMs < -45) {
    return color(ctx, "color.early", [
      `Way out in front of it. He was sitting dead red.`,
      `Too early — that pitch had him leaning.`,
    ]);
  }
  if (j.swung && j.deltaMs > 45) {
    return color(ctx, "color.late", [
      `Just a tick late. That fastball beat him.`,
      `He wasn't ready for that velocity.`,
    ]);
  }
  if (j.swung && j.contact === "solid" && j.contactQuality > 0.85) {
    return color(ctx, "color.barrel", [
      `That is what a barrel sounds like.`,
      `Right on the screws. Nothing you can do about that one.`,
    ]);
  }
  if (!j.swung && j.inStrikeZone && j.plateCoverage > 0.85) {
    return color(ctx, "color.taken-cookie", [
      `He can't take that pitch. Right down Broadway.`,
      `That's a mistake, and he watched it go by.`,
    ]);
  }
  if (!j.swung && !j.inStrikeZone) {
    return color(ctx, "color.good-take", [
      `Good discipline. He wasn't giving in there.`,
      `Nice take. That's a pitcher's pitch and he let it go.`,
    ]);
  }

  if (isHighLeverage(ctx.leverage) && ctx.rng() < 0.6) {
    return color(ctx, "color.tension", [
      `You can feel the tension in the building right now.`,
      `This is exactly the situation you play nine innings for.`,
      `Every pitch matters right here.`,
    ]);
  }

  // Otherwise stay quiet most of the time. Dead air is part of baseball radio.
  if (ctx.rng() > 0.25) return null;
  return color(ctx, "color.filler", [
    `${ctx.pitcher} is working quickly tonight.`,
    `The infield is playing him straight up.`,
    `You can hear this crowd starting to lean in.`,
  ]);
}

function color(ctx: NarrationContext, id: string, options: readonly string[]): Phrase {
  const fragment = choose(ctx.rng, id, options);
  return { id: fragment.id, text: fragment.text, speaker: "color", energy: 0.25 };
}

// --- helpers ---------------------------------------------------------------

function pickIndex(rng: Rng, length: number): number {
  return Math.min(length - 1, Math.floor(rng() * length));
}

function choose(rng: Rng, id: string, options: readonly string[]): CallFragment {
  const index = pickIndex(rng, options.length);
  return { id: `${id}.${index}`, text: options[index] as string };
}

function line(
  rng: Rng,
  id: string,
  options: readonly string[],
  speaker: Speaker = "announcer",
  energy = 0.3,
): Phrase {
  const fragment = choose(rng, id, options);
  return { id: fragment.id, text: fragment.text, speaker, energy };
}

function ordinalStrike(strikes: number): string {
  return strikes === 1 ? "one" : strikes === 2 ? "two" : "three";
}

const ORDINAL_INNINGS = [
  "",
  "first",
  "second",
  "third",
  "fourth",
  "fifth",
  "sixth",
  "seventh",
  "eighth",
  "ninth",
  "tenth",
  "eleventh",
  "twelfth",
];

function ordinalInning(inning: number): string {
  return ORDINAL_INNINGS[inning] ?? `${inning}th`;
}

function capitalize(text: string): string {
  return text.length === 0 ? text : text[0]!.toUpperCase() + text.slice(1);
}

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}
