import type { DifficultyConfig, DifficultyId } from "./Difficulty.ts";
import type { BatterRatings, PitcherRatings } from "./Player.ts";
import { modifyAiSkill, windowsForBatter } from "./Ratings.ts";
import type { PitchProfile } from "../timing/Timeline.ts";
import { isInStrikeZone, type PitchLocation } from "../timing/Timeline.ts";
import { judgeSwing, type SwingJudgment, type TimingWindows } from "../timing/SwingJudge.ts";

/**
 * BatterAI — opponent hitter when the human is pitching.
 *
 * Difficulty scales how tough the AI is for the pitcher: Rookie AI is looser
 * (easier to pitch to); Legend AI times well and protects with two strikes.
 * Batter contact/eye and pitcher stuff further bend timing and chase.
 */

export type Rng = () => number;

export interface BatterAIInput {
  balls: number;
  strikes: number;
  profile: PitchProfile;
  location: PitchLocation;
  /** Performance-clock plate arrival — AI swing is measured against this. */
  perceivedPlateMs: number;
  difficulty: DifficultyConfig;
  windows?: TimingWindows;
  batter?: BatterRatings;
  pitcher?: PitcherRatings;
  rng?: Rng;
}

/** How sharp the AI batter is (higher = harder on the pitcher). */
function aiSkill(id: DifficultyId): { sigmaMs: number; zoneDiscipline: number; chase: number } {
  switch (id) {
    case "rookie":
      return { sigmaMs: 95, zoneDiscipline: 0.55, chase: 0.22 };
    case "pro":
      return { sigmaMs: 70, zoneDiscipline: 0.7, chase: 0.28 };
    case "all-star":
      return { sigmaMs: 48, zoneDiscipline: 0.82, chase: 0.32 };
    case "legend":
      return { sigmaMs: 32, zoneDiscipline: 0.9, chase: 0.38 };
  }
}

function gaussian(rng: Rng): number {
  const u = Math.max(rng(), Number.EPSILON);
  const v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

export function decideBatterSwing(input: BatterAIInput): SwingJudgment {
  const rng = input.rng ?? Math.random;
  const batter = input.batter ?? { contact: 70, eye: 70, power: 70, speed: 70 };
  const pitcher = input.pitcher ?? { velocity: 70, command: 70, stuff: 70 };
  const skill = modifyAiSkill(aiSkill(input.difficulty.id), batter, pitcher);
  const inZone = isInStrikeZone(input.location);
  const { balls, strikes } = input;

  const baseWindows = input.windows ?? {
    perfectWindowMs: input.difficulty.perfectWindowMs,
    contactWindowMs: input.difficulty.contactWindowMs,
  };
  const windows = windowsForBatter(baseWindows, batter);

  let swingProb: number;
  if (inZone) {
    swingProb = 0.55 + skill.zoneDiscipline * 0.4;
    if (strikes >= 2) swingProb = Math.min(0.97, swingProb + 0.12);
    if (balls >= 3 && strikes === 0) swingProb *= 0.45;
  } else {
    swingProb = skill.chase * (input.profile.type === "fastball" ? 0.75 : 1.05);
    if (strikes >= 2) swingProb = Math.min(0.85, swingProb + 0.35);
    if (balls >= 3 && strikes < 2) swingProb *= 0.35;
  }

  // Hanging meatball (near middle) gets crushed more often.
  const meatball =
    Math.abs(input.location.horizontal) < 0.35 && Math.abs(input.location.vertical) < 0.35;
  if (meatball) swingProb = Math.min(0.98, swingProb + 0.2);

  const swung = rng() < swingProb;
  if (!swung) {
    return judgeSwing({
      swung: false,
      swingPerfMs: 0,
      perceivedPlateMs: input.perceivedPlateMs,
      calibrationMs: 0,
      location: input.location,
      windows,
    });
  }

  // Off-speed: AI sometimes early (looking FB) — more so on lower difficulties
  // and against high-stuff pitchers.
  let biasMs = 0;
  if (input.profile.type !== "fastball") {
    const earlyBias =
      (input.difficulty.id === "legend" ? 8 : input.difficulty.id === "rookie" ? 45 : 25) +
      skill.offspeedEarlyMs;
    biasMs = -earlyBias * (0.4 + rng() * 0.6);
  }

  const errorMs = gaussian(rng) * skill.sigmaMs + biasMs;
  const swingPerfMs = input.perceivedPlateMs + errorMs;

  return judgeSwing({
    swung: true,
    swingPerfMs,
    perceivedPlateMs: input.perceivedPlateMs,
    calibrationMs: 0,
    location: input.location,
    windows,
  });
}
