import { LOCATION_EXTENT, type PitchType } from "../timing/Timeline.ts";
import {
  formatAvg,
  formatIp,
  type LiveSnapshot,
  type PitchMarker,
} from "../game/LiveStats.ts";
import { formatCount } from "../game/GameState.ts";
import {
  formatBats,
  formatThrows,
  spokenHand,
  batsHand,
  throwsHand,
  formatBatterTeaser,
  formatPitcherTeaser,
} from "../game/Teams.ts";

/**
 * GamedayBoard — MLB.com-style live game interface.
 *
 * Audio still carries the game; this is the broadcast graphic layer: scorebug,
 * strike-zone pitch plot, current at-bat pitch tray, line score, and box lines.
 */

const PITCH_COLORS: Record<PitchType, string> = {
  fastball: "#e74c3c",
  slider: "#f1c40f",
  curveball: "#3498db",
  changeup: "#2ecc71",
};

const PITCH_SHORT: Record<PitchType, string> = {
  fastball: "FF",
  slider: "SL",
  curveball: "CU",
  changeup: "CH",
};

export class GamedayBoard {
  private readonly root: HTMLElement;
  private playerTeamShort: string | null = null;

  constructor(root: HTMLElement) {
    this.root = root;
  }

  setPlayerTeam(shortName: string | null): void {
    this.playerTeamShort = shortName;
  }

  render(live: LiveSnapshot): void {
    const { game } = live;
    const halfLabel = game.gameOver
      ? "Final"
      : `${game.half === "top" ? "Top" : "Bot"} ${game.inning}`;

    this.root.replaceChildren(
      el("div", "gd-scorebug", [
        this.teamRow(
          game.awayTeam,
          game.score.away,
          live.awayLine,
          !game.gameOver && game.half === "top",
          this.playerTeamShort === game.awayTeam,
        ),
        this.teamRow(
          game.homeTeam,
          game.score.home,
          live.homeLine,
          !game.gameOver && game.half === "bottom",
          this.playerTeamShort === game.homeTeam,
        ),
        el("div", "gd-bug-meta", [
          el("div", "gd-inning", [text(halfLabel)]),
          this.outsDots(game.outs),
          this.countBlock(game.balls, game.strikes),
          this.diamond(game.bases),
        ]),
      ]),
      el("div", "gd-main", [
        this.matchup(live),
        this.pitchPlot(live),
        this.pitchTray(live),
      ]),
      this.lineScore(live),
      el("div", "gd-box", [
        el("div", "gd-box-team", [
          this.battingTable(game.awayTeam, live.awayBatters, game.battingTeam === game.awayTeam ? game.batter : null),
          this.pitchingTable(
            game.awayTeam,
            live.awayPitcher,
            !game.gameOver && game.half === "bottom",
          ),
        ]),
        el("div", "gd-box-team", [
          this.battingTable(game.homeTeam, live.homeBatters, game.battingTeam === game.homeTeam ? game.batter : null),
          this.pitchingTable(
            game.homeTeam,
            live.homePitcher,
            !game.gameOver && game.half === "top",
          ),
        ]),
      ]),
    );
  }

  private teamRow(
    name: string,
    runs: number,
    line: number[],
    batting: boolean,
    yours: boolean,
  ): HTMLElement {
    const label = yours ? `${name} (YOU)` : name;
    return el("div", `gd-team${batting ? " gd-team--batting" : ""}${yours ? " gd-team--yours" : ""}`, [
      el("span", "gd-team-name", [text(label)]),
      el("span", "gd-team-runs", [text(String(runs))]),
      el("span", "gd-team-line", [text(line.map((r) => (r === 0 ? "·" : String(r))).join(" "))]),
    ]);
  }

  private outsDots(outs: number): HTMLElement {
    return el(
      "div",
      "gd-outs",
      [0, 1, 2].map((i) => el("span", `gd-out${i < outs ? " gd-out--on" : ""}`)),
    );
  }

  private countBlock(balls: number, strikes: number): HTMLElement {
    return el("div", "gd-count", [
      el("span", "gd-count-label", [text("B")]),
      el("span", "gd-count-val", [text(String(balls))]),
      el("span", "gd-count-label", [text("S")]),
      el("span", "gd-count-val", [text(String(strikes))]),
    ]);
  }

  private diamond(bases: LiveSnapshot["game"]["bases"]): HTMLElement {
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "gd-diamond");
    svg.setAttribute("viewBox", "0 0 40 40");
    svg.setAttribute("aria-label", `Bases: 1st ${bases.first ? "occupied" : "empty"}, 2nd ${bases.second ? "occupied" : "empty"}, 3rd ${bases.third ? "occupied" : "empty"}`);

    const spots: Array<[number, number, boolean, string]> = [
      [20, 8, bases.second, "2B"],
      [32, 20, bases.first, "1B"],
      [8, 20, bases.third, "3B"],
    ];
    for (const [x, y, on, label] of spots) {
      const base = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      base.setAttribute("x", String(x - 5));
      base.setAttribute("y", String(y - 5));
      base.setAttribute("width", "10");
      base.setAttribute("height", "10");
      base.setAttribute("transform", `rotate(45 ${x} ${y})`);
      base.setAttribute("class", on ? "gd-base gd-base--on" : "gd-base");
      base.setAttribute("aria-label", label);
      svg.append(base);
    }
    return svg as unknown as HTMLElement;
  }

  private matchup(live: LiveSnapshot): HTMLElement {
    const { game } = live;
    const batters = game.battingTeam === game.awayTeam ? live.awayBatters : live.homeBatters;
    const batter = batters.find((b) => b.name === game.batter);
    const pitcher = game.half === "top" ? live.homePitcher : live.awayPitcher;

    const batterLine = batter
      ? `${batter.h}-${batter.ab}, ${batter.rbi} RBI`
      : "0-0";
    const pitcherLine = `${formatIp(pitcher.outs)} IP · ${pitcher.pitches} P · ${pitcher.k} K`;

    const batterTeaser = formatBatterTeaser(game.batter);
    const pitcherTeaser = formatPitcherTeaser(game.pitcher);

    return el("div", "gd-matchup", [
      el("div", "gd-matchup-side", [
        el("div", "gd-matchup-role", [text("At Bat")]),
        el("div", "gd-matchup-name", [
          text(game.batter),
          handBadge(formatBats(game.batter), spokenHand(batsHand(game.batter), "bats")),
        ]),
        el("div", "gd-matchup-stat", [text(batterLine)]),
        el("div", "gd-matchup-stat", [text(`${formatAvg(batter?.h ?? 0, batter?.ab ?? 0)} AVG`)]),
        ...(batterTeaser ? [el("div", "gd-matchup-stat gd-matchup-ratings", [text(batterTeaser)])] : []),
      ]),
      el("div", "gd-matchup-vs", [text("VS")]),
      el("div", "gd-matchup-side gd-matchup-side--pitcher", [
        el("div", "gd-matchup-role", [text("Pitching")]),
        el("div", "gd-matchup-name", [
          text(game.pitcher),
          handBadge(formatThrows(game.pitcher), spokenHand(throwsHand(game.pitcher), "throws")),
        ]),
        el("div", "gd-matchup-stat", [text(pitcherLine)]),
        el("div", "gd-matchup-stat", [text(`${pitcher.h} H · ${pitcher.bb} BB`)]),
        ...(pitcherTeaser ? [el("div", "gd-matchup-stat gd-matchup-ratings", [text(pitcherTeaser)])] : []),
      ]),
      el("div", "gd-matchup-count", [
        el("div", "gd-matchup-count-label", [text("Count")]),
        el("div", "gd-matchup-count-val", [text(formatCount(game.balls, game.strikes))]),
      ]),
    ]);
  }

  private pitchPlot(live: LiveSnapshot): HTMLElement {
    const wrap = el("div", "gd-zone-wrap", []);
    wrap.setAttribute("role", "img");
    wrap.setAttribute("aria-label", zoneAria(live.lastPitch));

    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "gd-zone");
    svg.setAttribute("viewBox", "0 0 200 240");

    // Catcher's view plot area. Zone is the inner rectangle; shadow zone around it.
    const zx = 60;
    const zy = 50;
    const zw = 80;
    const zh = 110;

    const plate = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
    plate.setAttribute("points", "70,175 130,175 120,190 80,190");
    plate.setAttribute("class", "gd-plate");
    svg.append(plate);

    const shadow = document.createElementNS("http://www.w3.org/2000/svg", "rect");
    shadow.setAttribute("x", "40");
    shadow.setAttribute("y", "30");
    shadow.setAttribute("width", "120");
    shadow.setAttribute("height", "150");
    shadow.setAttribute("class", "gd-zone-shadow");
    svg.append(shadow);

    const zone = document.createElementNS("http://www.w3.org/2000/svg", "rect");
    zone.setAttribute("x", String(zx));
    zone.setAttribute("y", String(zy));
    zone.setAttribute("width", String(zw));
    zone.setAttribute("height", String(zh));
    zone.setAttribute("class", "gd-zone-box");
    svg.append(zone);

    // 3x3 grid inside the zone
    for (let i = 1; i < 3; i++) {
      const v = document.createElementNS("http://www.w3.org/2000/svg", "line");
      v.setAttribute("x1", String(zx + (zw * i) / 3));
      v.setAttribute("x2", String(zx + (zw * i) / 3));
      v.setAttribute("y1", String(zy));
      v.setAttribute("y2", String(zy + zh));
      v.setAttribute("class", "gd-zone-grid");
      svg.append(v);
      const h = document.createElementNS("http://www.w3.org/2000/svg", "line");
      h.setAttribute("x1", String(zx));
      h.setAttribute("x2", String(zx + zw));
      h.setAttribute("y1", String(zy + (zh * i) / 3));
      h.setAttribute("y2", String(zy + (zh * i) / 3));
      h.setAttribute("class", "gd-zone-grid");
      svg.append(h);
    }

    const title = document.createElementNS("http://www.w3.org/2000/svg", "text");
    title.setAttribute("x", "100");
    title.setAttribute("y", "18");
    title.setAttribute("class", "gd-zone-title");
    title.textContent = "Pitch Tracker";
    svg.append(title);

    // Trail: current AB pitches, faded; last pitch emphasized.
    const abPitches = live.currentAtBat.pitches;
    abPitches.forEach((pitch, index) => {
      const isLast = index === abPitches.length - 1;
      const [cx, cy] = locToSvg(pitch.location, zx, zy, zw, zh);
      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute("cx", String(cx));
      circle.setAttribute("cy", String(cy));
      circle.setAttribute("r", isLast ? "9" : "6");
      circle.setAttribute("fill", PITCH_COLORS[pitch.type]);
      circle.setAttribute("class", isLast ? "gd-pitch gd-pitch--last" : "gd-pitch");
      circle.setAttribute("opacity", isLast ? "1" : "0.55");
      svg.append(circle);

      if (isLast) {
        const label = document.createElementNS("http://www.w3.org/2000/svg", "text");
        label.setAttribute("x", String(cx));
        label.setAttribute("y", String(cy + 3.5));
        label.setAttribute("class", "gd-pitch-num");
        label.textContent = String(pitch.number);
        svg.append(label);
      }
    });

    // Legend
    const legendY = 220;
    (Object.keys(PITCH_COLORS) as PitchType[]).forEach((type, i) => {
      const x = 28 + i * 44;
      const c = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      c.setAttribute("cx", String(x));
      c.setAttribute("cy", String(legendY));
      c.setAttribute("r", "4");
      c.setAttribute("fill", PITCH_COLORS[type]);
      svg.append(c);
      const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
      t.setAttribute("x", String(x + 8));
      t.setAttribute("y", String(legendY + 3));
      t.setAttribute("class", "gd-legend");
      t.textContent = PITCH_SHORT[type];
      svg.append(t);
    });

    wrap.append(svg);

    if (live.lastPitch) {
      wrap.append(
        el("div", "gd-last-pitch", [
          el("span", "gd-last-velo", [text(`${live.lastPitch.velocityMph}`)]),
          el("span", "gd-last-unit", [text("mph")]),
          el("span", "gd-last-type", [text(live.lastPitch.label)]),
          el("span", `gd-last-code gd-last-code--${live.lastPitch.code}`, [
            text(resultLabel(live.lastPitch)),
          ]),
        ]),
      );
    } else {
      wrap.append(el("div", "gd-last-pitch gd-last-pitch--empty", [text("Awaiting first pitch")]));
    }

    return wrap;
  }

  private pitchTray(live: LiveSnapshot): HTMLElement {
    const pitches = live.currentAtBat.pitches;
    return el("div", "gd-tray", [
      el("div", "gd-tray-head", [text(`This AB · ${live.currentAtBat.batter}`)]),
      el(
        "ol",
        "gd-tray-list",
        pitches.length === 0
          ? [el("li", "gd-tray-empty", [text("No pitches yet")])]
          : [...pitches].reverse().map((p) =>
              el("li", "gd-tray-item", [
                el("span", "gd-tray-num", [text(String(p.number))]),
                el("span", "gd-tray-dot", [], { background: PITCH_COLORS[p.type] }),
                el("span", "gd-tray-type", [text(`${PITCH_SHORT[p.type]} ${p.velocityMph}`)]),
                el("span", `gd-tray-code gd-tray-code--${p.code}`, [text(p.code)]),
                el("span", "gd-tray-result", [text(resultLabel(p))]),
              ]),
            ),
      ),
    ]);
  }

  private lineScore(live: LiveSnapshot): HTMLElement {
    const innings = Math.max(9, live.awayLine.length, live.homeLine.length, live.game.inning);
    const headers = Array.from({ length: innings }, (_, i) => String(i + 1));

    const cellFor = (name: string, line: number[], inningIndex: number): string => {
      const inning = inningIndex + 1;
      const isAway = name === live.game.awayTeam;
      const completed = inning < live.game.inning || live.game.gameOver;
      const currentHalfDone =
        inning === live.game.inning && (live.game.half === "bottom" || isAway || live.game.gameOver);
      if (!completed && !currentHalfDone) return "";
      return String(line[inningIndex] ?? 0);
    };

    const row = (name: string, line: number[], total: number): HTMLElement =>
      el("tr", "", [
        el("th", "", [text(name)]),
        ...Array.from({ length: innings }, (_, i) => el("td", "", [text(cellFor(name, line, i))])),
        el("td", "gd-line-total", [text(String(total))]),
      ]);

    return el("div", "gd-linescore-wrap", [
      el("table", "gd-linescore", [
        el("thead", "", [
          el("tr", "", [
            el("th", "", [text("")]),
            ...headers.map((h) => el("th", "", [text(h)])),
            el("th", "", [text("R")]),
          ]),
        ]),
        el("tbody", "", [
          row(live.game.awayTeam, live.awayLine, live.game.score.away),
          row(live.game.homeTeam, live.homeLine, live.game.score.home),
        ]),
      ]),
    ]);
  }

  private battingTable(
    team: string,
    batters: LiveSnapshot["awayBatters"],
    activeName: string | null,
  ): HTMLElement {
    return el("div", "gd-batting", [
      el("div", "gd-batting-head", [text(team)]),
      el("table", "gd-stat-table", [
        el("thead", "", [
          el("tr", "", ["", "B", "AB", "R", "H", "RBI", "BB", "K", "AVG"].map((h) => el("th", "", [text(h)]))),
        ]),
        el(
          "tbody",
          "",
          batters.map((b) =>
            el("tr", b.name === activeName ? "gd-row--active" : "", [
              el("th", "", [text(b.name)]),
              el("td", "gd-hand-cell", [text(formatBats(b.name))]),
              el("td", "", [text(String(b.ab))]),
              el("td", "", [text(String(b.r))]),
              el("td", "", [text(String(b.h))]),
              el("td", "", [text(String(b.rbi))]),
              el("td", "", [text(String(b.bb))]),
              el("td", "", [text(String(b.k))]),
              el("td", "", [text(formatAvg(b.h, b.ab))]),
            ]),
          ),
        ),
      ]),
    ]);
  }

  private pitchingTable(
    team: string,
    pitcher: LiveSnapshot["awayPitcher"],
    active: boolean,
  ): HTMLElement {
    return el("div", "gd-pitching", [
      el("div", "gd-batting-head gd-batting-head--sub", [text(`${team} pitching`)]),
      el("table", "gd-stat-table", [
        el("thead", "", [
          el("tr", "", ["", "IP", "H", "R", "ER", "BB", "K", "P"].map((h) => el("th", "", [text(h)]))),
        ]),
        el("tbody", "", [
          el("tr", active ? "gd-row--active" : "", [
            el("th", "", [
              text(pitcher.name),
              handBadge(formatThrows(pitcher.name), spokenHand(throwsHand(pitcher.name), "throws")),
            ]),
            el("td", "", [text(formatIp(pitcher.outs))]),
            el("td", "", [text(String(pitcher.h))]),
            el("td", "", [text(String(pitcher.r))]),
            el("td", "", [text(String(pitcher.er))]),
            el("td", "", [text(String(pitcher.bb))]),
            el("td", "", [text(String(pitcher.k))]),
            el("td", "", [text(String(pitcher.pitches))]),
          ]),
        ]),
      ]),
    ]);
  }
}

/** Map zone units onto the strike-zone SVG. Catcher's view: −H left (inside to RHB). */
function locToSvg(
  location: PitchMarker["location"],
  zx: number,
  zy: number,
  zw: number,
  zh: number,
): [number, number] {
  const cx = zx + zw / 2;
  const cy = zy + zh / 2;
  // Full plot spans ±LOCATION_EXTENT mapped onto the shadow box (~1.5× zone).
  const scaleX = zw / 2;
  const scaleY = zh / 2;
  const x = cx + (location.horizontal / 1) * scaleX;
  const y = cy - (location.vertical / 1) * scaleY;
  // Clamp to shadow so wild pitches stay on-plot.
  const minX = 40;
  const maxX = 160;
  const minY = 30;
  const maxY = 180;
  const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
  // Also allow outside-zone markers in the shadow using extent scale
  const x2 = cx + (location.horizontal / LOCATION_EXTENT) * ((maxX - minX) / 2);
  const y2 = cy - (location.vertical / LOCATION_EXTENT) * ((maxY - minY) / 2);
  // Prefer zone-relative for in/near zone, extent for far — blend by distance
  const dist = Math.max(Math.abs(location.horizontal), Math.abs(location.vertical));
  if (dist <= 1.15) return [clamp(x, minX, maxX), clamp(y, minY, maxY)];
  return [clamp(x2, minX, maxX), clamp(y2, minY, maxY)];
}

function resultLabel(p: PitchMarker): string {
  switch (p.result) {
    case "ball":
      return "Ball";
    case "called-strike":
      return "Called Strike";
    case "swinging-strike":
      return "Swing & Miss";
    case "foul-ball":
      return "Foul";
    case "single":
      return "Single";
    case "double":
      return "Double";
    case "home-run":
      return "Home Run";
    case "ground-out":
      return "Groundout";
    case "fly-out":
      return "Flyout";
    case "line-out":
      return "Lineout";
    case "pop-up":
      return "Popup";
  }
}

function zoneAria(last: PitchMarker | null): string {
  if (!last) return "Strike zone pitch tracker, no pitches yet";
  return `Last pitch: ${last.velocityMph} mile per hour ${last.label}, ${resultLabel(last)}`;
}

function handBadge(label: string, spoken: string): HTMLElement {
  const node = el("span", "gd-hand", [text(` ${label}`)]);
  node.title = spoken;
  node.setAttribute("aria-label", spoken);
  return node;
}

function el(
  tag: string,
  className: string,
  children: Array<HTMLElement | SVGElement | Text> = [],
  style?: Record<string, string>,
): HTMLElement {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (style) Object.assign(node.style, style);
  for (const child of children) node.append(child);
  return node;
}

function text(value: string): Text {
  return document.createTextNode(value);
}
