import type { AudioEngine } from "../audio/AudioEngine.ts";
import type { SwingInput } from "../timing/SwingInput.ts";
import { noiseBurst } from "../audio/voices/shared.ts";

/**
 * Calibration — measure this player's constant timing offset and subtract it.
 *
 * Without this the game is broken on a large fraction of real hardware, and not in
 * a way anyone would diagnose correctly. Bluetooth headphones routinely add 150–300 ms
 * of output latency. The ClockBridge already accounts for the part the browser
 * *reports*, but nothing in the platform knows about the delay inside the headphones
 * themselves, or about the player's own reaction bias — most people tap consistently
 * early or consistently late by 10–40 ms, and it is stable enough to correct for.
 *
 * A 30 ms perfect window against an uncorrected 200 ms offset is not a hard game,
 * it is an impossible one. So: eight beats, tap along, take the median.
 *
 * Median rather than mean, because one distracted tap in eight would drag a mean
 * far enough to matter and would leave no trace of having done so.
 */

const STORAGE_KEY = "baseballradio.calibrationMs";

const BEAT_COUNT = 10;
/** Taps discarded from the front while the player finds the pulse. */
const WARMUP_BEATS = 2;
const BEAT_INTERVAL_SEC = 0.85;
const LEAD_IN_SEC = 0.7;
/** Taps further than this from any beat are noise, not attempts. */
const MAX_USABLE_ERROR_MS = 400;
const CLAMP_MS = 500;

export interface CalibrationOptions {
  onStatus: (text: string) => void;
}

export class Calibration {
  private readonly engine: AudioEngine;
  private readonly input: SwingInput;
  private readonly onStatus: (text: string) => void;
  private _offsetMs: number;
  private running = false;

  constructor(engine: AudioEngine, input: SwingInput, options: CalibrationOptions) {
    this.engine = engine;
    this.input = input;
    this.onStatus = options.onStatus;
    this._offsetMs = loadStoredOffset();
    this.report();
  }

  get offsetMs(): number {
    return this._offsetMs;
  }

  get isRunning(): boolean {
    return this.running;
  }

  reset(): void {
    this._offsetMs = 0;
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      /* storage unavailable; the in-memory value still applies for this session */
    }
    this.report();
  }

  /** Run the metronome. Resolves with the measured offset in ms. */
  async run(): Promise<number> {
    if (this.running) return this._offsetMs;
    this.running = true;

    try {
      const { engine } = this;
      const ctx = engine.ctx;
      const firstBeat = ctx.currentTime + LEAD_IN_SEC;
      const beats: number[] = [];

      for (let i = 0; i < BEAT_COUNT; i++) {
        const at = firstBeat + i * BEAT_INTERVAL_SEC;
        beats.push(at);
        playClick(engine, at, i % 4 === 0);
      }

      this.onStatus(`Tap SPACE on each click (${BEAT_COUNT})...`);
      const taps = await this.collectTaps(beats);

      const errors = this.measureErrors(beats, taps);
      if (errors.length < 3) {
        this.onStatus("Not enough taps registered — try again.");
        return this._offsetMs;
      }

      const measured = clamp(median(errors), -CLAMP_MS, CLAMP_MS);
      this._offsetMs = measured;
      persist(measured);
      this.report(errors.length, spread(errors));
      return measured;
    } finally {
      this.running = false;
      this.input.disarm();
    }
  }

  /** Arm the real SwingInput repeatedly so calibration measures the same code path. */
  private collectTaps(beats: readonly number[]): Promise<number[]> {
    const taps: number[] = [];
    const lastBeat = beats[beats.length - 1] as number;
    const endAt = lastBeat + BEAT_INTERVAL_SEC;

    return new Promise((resolve) => {
      const rearm = (): void => {
        this.input.arm((event) => {
          taps.push(event.perfMs);
          rearm();
        });
      };
      rearm();

      const poll = setInterval(() => {
        if (this.engine.ctx.currentTime < endAt) return;
        clearInterval(poll);
        this.input.disarm();
        resolve(taps);
      }, 20);
    });
  }

  /**
   * Signed error per tap against its nearest beat. Positive means the player tapped
   * late relative to what they heard.
   */
  private measureErrors(beats: readonly number[], taps: readonly number[]): number[] {
    const clock = this.engine.clock;
    // Perceived beat times, resolved now rather than when they were scheduled, so
    // the freshest clock offset is used.
    const perceived = beats.map((beat) => clock.audioToPerf(beat));
    const halfBeatMs = (BEAT_INTERVAL_SEC * 1000) / 2;

    const errors: number[] = [];
    for (const tap of taps) {
      let matchedIndex = -1;
      let smallestError = Number.POSITIVE_INFINITY;
      for (let i = 0; i < perceived.length; i++) {
        const error = tap - (perceived[i] as number);
        if (Math.abs(error) < Math.abs(smallestError)) {
          smallestError = error;
          matchedIndex = i;
        }
      }

      if (matchedIndex < WARMUP_BEATS) continue; // still finding the pulse
      if (Math.abs(smallestError) > MAX_USABLE_ERROR_MS) continue; // not an attempt
      if (Math.abs(smallestError) > halfBeatMs) continue; // ambiguous between beats
      errors.push(smallestError);
    }
    return errors;
  }

  private report(sampleCount?: number, spreadMs?: number): void {
    if (this._offsetMs === 0 && sampleCount === undefined) {
      this.onStatus("Not calibrated — run this before you judge your timing.");
      return;
    }
    const sign = this._offsetMs >= 0 ? "+" : "";
    const detail =
      sampleCount === undefined
        ? " (stored)"
        : ` from ${sampleCount} taps, spread ${(spreadMs ?? 0).toFixed(0)} ms`;
    this.onStatus(`Offset ${sign}${this._offsetMs.toFixed(1)} ms${detail}`);
  }
}

/** Accented downbeats make the pulse easy to lock onto. */
function playClick(engine: AudioEngine, at: number, accent: boolean): void {
  noiseBurst(engine, engine.busInput("field"), {
    at,
    duration: 0.03,
    color: "white",
    frequency: accent ? 3200 : 2000,
    q: 2.5,
    peak: accent ? 0.7 : 0.45,
    attack: 0.001,
  });
}

function loadStoredOffset(): number {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw === null) return 0;
    const value = Number.parseFloat(raw);
    return Number.isFinite(value) ? clamp(value, -CLAMP_MS, CLAMP_MS) : 0;
  } catch {
    return 0;
  }
}

function persist(value: number): void {
  try {
    localStorage.setItem(STORAGE_KEY, String(value));
  } catch {
    /* private browsing, quota, etc. — not worth failing the calibration over */
  }
}

function median(values: readonly number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = sorted.length >> 1;
  if (sorted.length % 2 === 1) return sorted[mid] as number;
  return ((sorted[mid - 1] as number) + (sorted[mid] as number)) / 2;
}

function spread(values: readonly number[]): number {
  return Math.max(...values) - Math.min(...values);
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
