import {
  LOCATION_EXTENT,
  type PitchLocation,
  type PitchProfile,
  type PitchType,
  clamp,
} from "../timing/Timeline.ts";
import { getDifficulty, type DifficultyConfig, type DifficultyId } from "./Difficulty.ts";
import type { PitcherRatings } from "./Player.ts";
import { commandScatter, profileForPitcher, stuffOffspeedBias } from "./Ratings.ts";

export { PROFILES } from "./pitchProfiles.ts";

/**
 * PitchSelector — what the pitcher throws, and where he tries to put it.
 *
 * Count-aware, and gated by difficulty: Rookie pins the flight time to the pulse
 * so the batter can learn the rhythm; higher tiers unlock offspeed and expand
 * the zone the pitcher is willing to miss in. Per-pitcher ratings bend velo,
 * command scatter, and two-strike miss-pitch rate.
 */

export type Rng = () => number;

const FULL_ARSENAL: readonly PitchType[] = ["fastball", "fastball", "slider", "curveball", "changeup"];
const FB_HEAVY: readonly PitchType[] = [
  "fastball",
  "fastball",
  "fastball",
  "fastball",
  "slider",
  "changeup",
];

const STOCK_PITCHER: PitcherRatings = { velocity: 70, command: 70, stuff: 70 };

export interface PitchCall {
  profile: PitchProfile;
  location: PitchLocation;
}

export class PitchSelector {
  private readonly rng: Rng;
  private difficulty: DifficultyConfig = getDifficulty();
  private pitcher: PitcherRatings = STOCK_PITCHER;

  constructor(rng: Rng = Math.random) {
    this.rng = rng;
  }

  setDifficulty(id: DifficultyId | DifficultyConfig): void {
    this.difficulty = typeof id === "string" ? getDifficulty(id) : id;
  }

  getDifficulty(): DifficultyConfig {
    return this.difficulty;
  }

  setPitcher(ratings: PitcherRatings | undefined): void {
    this.pitcher = ratings ?? STOCK_PITCHER;
  }

  select(balls: number, strikes: number): PitchCall {
    const { pitchMix, locationAggression } = this.difficulty;

    if (pitchMix === "fastball") {
      return {
        profile: profileForPitcher("fastball", this.pitcher),
        location: this.pickLocation(locationAggression),
      };
    }

    const type = this.pickType(balls, strikes, pitchMix);
    const ahead = strikes - balls;
    const aggression = clamp(locationAggression * 0.65 + ahead * 0.28, 0.15, 1.45);
    return {
      profile: profileForPitcher(type, this.pitcher),
      location: this.pickLocation(aggression),
    };
  }

  private pickType(balls: number, strikes: number, mix: DifficultyConfig["pitchMix"]): PitchType {
    const missBias = stuffOffspeedBias(this.pitcher);
    if (balls >= 3 && strikes < 2) return "fastball";
    if (strikes >= 2 && balls < 3) {
      const goOffspeed = this.rng() < 0.45 + missBias * 0.25;
      if (mix === "fb-heavy") {
        if (!goOffspeed && this.rng() < 0.55) return "fastball";
        return this.rng() < 0.5 ? "slider" : "changeup";
      }
      if (!goOffspeed && this.rng() < 0.4) return "fastball";
      return this.rng() < 0.6 ? (this.rng() < 0.5 ? "slider" : "curveball") : "changeup";
    }
    const arsenal = mix === "fb-heavy" ? FB_HEAVY : FULL_ARSENAL;
    const index = Math.floor(this.rng() * arsenal.length);
    return arsenal[Math.min(index, arsenal.length - 1)] as PitchType;
  }

  private pickLocation(aggression: number): PitchLocation {
    const command = commandScatter(this.pitcher);
    const horizontal = gaussian(this.rng) * aggression + gaussian(this.rng) * command;
    const vertical = gaussian(this.rng) * aggression * 0.85 + gaussian(this.rng) * command - 0.18;
    return {
      horizontal: clamp(horizontal, -LOCATION_EXTENT, LOCATION_EXTENT),
      vertical: clamp(vertical, -LOCATION_EXTENT, LOCATION_EXTENT),
    };
  }
}

function gaussian(rng: Rng): number {
  const u = Math.max(rng(), Number.EPSILON);
  const v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

export function describeLocation(location: PitchLocation): string {
  const h = location.horizontal;
  const v = location.vertical;
  const inside = h < -1;
  const outside = h > 1;
  const high = v > 1;
  const low = v < -1;

  if (low && Math.abs(h) <= 1) return v < -1.6 ? "in the dirt" : "down below the zone";
  if (high && Math.abs(h) <= 1) return "up out of the zone";
  if (inside) return low ? "in and off the plate" : "way inside";
  if (outside) return low ? "low and away" : "off the outside corner";

  if (Math.abs(h) > 0.75 && Math.abs(v) > 0.75) return "painted on the corner";
  if (h > 0.75) return "on the outside corner";
  if (h < -0.75) return "in on the hands";
  if (v > 0.75) return "up at the letters";
  if (v < -0.75) return "down at the knees";
  return "right down the middle";
}
