import type { PitchCall } from "../game/PitchSelector.ts";
import { PROFILES } from "../game/PitchSelector.ts";
import {
  CHASE_TARGETS,
  describePitchCall,
  loadSavedPitchCall,
  movePitchTarget,
  PITCH_TYPE_OPTIONS,
  savePitchCall,
  targetById,
  ZONE_TARGETS,
} from "../game/PitchTargets.ts";
import type { PitchType } from "../timing/Timeline.ts";

/**
 * PitchCallPanel — large-button type + zone pad before a human pitch.
 *
 * Touch-first radiogroups, arrow/1–4 keys, aria-live summary, Space to throw
 * while waiting for a call (release timing arms only after confirm).
 */

export class PitchCallPanel {
  private readonly root: HTMLElement;
  private typeButtons = new Map<PitchType, HTMLButtonElement>();
  private locationButtons = new Map<string, HTMLButtonElement>();
  private summary!: HTMLElement;
  private throwButton!: HTMLButtonElement;
  private type: PitchType = "fastball";
  private targetId = "low-away";
  private active = false;
  private pending: {
    resolve: (call: PitchCall) => void;
    reject: (reason: Error) => void;
  } | null = null;

  private readonly onKeyDown = (event: KeyboardEvent): void => {
    if (!this.active || this.root.hidden) return;
    if (isTextEntry(event.target)) return;

    // Space confirms throw while waiting — capture so SwingInput doesn't count a flinch.
    if ((event.code === "Space" || event.key === " ") && this.pending) {
      if (event.repeat) {
        event.preventDefault();
        return;
      }
      event.preventDefault();
      event.stopImmediatePropagation();
      this.confirm();
      return;
    }

    if (!this.pending && !this.active) return;

    if (event.key >= "1" && event.key <= "4") {
      const index = Number(event.key) - 1;
      const opt = PITCH_TYPE_OPTIONS[index];
      if (opt) {
        event.preventDefault();
        this.setType(opt.id, true);
      }
      return;
    }

    if (event.key === "ArrowLeft" || event.key === "ArrowRight" || event.key === "ArrowUp" || event.key === "ArrowDown") {
      event.preventDefault();
      const dx = event.key === "ArrowLeft" ? -1 : event.key === "ArrowRight" ? 1 : 0;
      const dy = event.key === "ArrowUp" ? -1 : event.key === "ArrowDown" ? 1 : 0;
      const next = movePitchTarget(this.targetId, dx, dy);
      this.setTarget(next.id, true);
      this.locationButtons.get(next.id)?.focus();
    }
  };

  constructor(root: HTMLElement) {
    this.root = root;
    const saved = loadSavedPitchCall();
    this.type = saved.type;
    this.targetId = saved.targetId;
    this.mount();
    this.setActive(false);
    window.addEventListener("keydown", this.onKeyDown, true);
  }

  private mount(): void {
    this.root.className = "pitch-call";
    this.root.setAttribute("role", "region");
    this.root.setAttribute("aria-label", "Pitch call");

    const typeGroup = document.createElement("div");
    typeGroup.className = "pitch-call-types";
    typeGroup.setAttribute("role", "radiogroup");
    typeGroup.setAttribute("aria-label", "Pitch type");

    for (const opt of PITCH_TYPE_OPTIONS) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "pitch-call-type";
      btn.dataset.type = opt.id;
      btn.setAttribute("role", "radio");
      btn.setAttribute("aria-label", opt.label);
      btn.textContent = opt.short;
      btn.addEventListener("click", () => {
        this.setType(opt.id, true);
        btn.focus();
      });
      this.typeButtons.set(opt.id, btn);
      typeGroup.append(btn);
    }

    const zoneWrap = document.createElement("div");
    zoneWrap.className = "pitch-call-location";
    zoneWrap.setAttribute("role", "radiogroup");
    zoneWrap.setAttribute("aria-label", "Pitch location");

    const zone = document.createElement("div");
    zone.className = "pitch-call-zone";
    zone.setAttribute("aria-hidden", "false");
    for (const target of ZONE_TARGETS) {
      zone.append(this.makeLocationButton(target.id, target.label, "pitch-call-cell"));
    }

    const chase = document.createElement("div");
    chase.className = "pitch-call-chase";
    for (const target of CHASE_TARGETS) {
      chase.append(this.makeLocationButton(target.id, target.label, "pitch-call-chase-btn"));
    }
    zoneWrap.append(zone, chase);

    this.summary = document.createElement("p");
    this.summary.className = "pitch-call-summary";
    this.summary.setAttribute("role", "status");
    this.summary.setAttribute("aria-live", "polite");

    this.throwButton = document.createElement("button");
    this.throwButton.type = "button";
    this.throwButton.className = "primary pitch-call-throw";
    this.throwButton.id = "throw-pitch";
    this.throwButton.textContent = "Throw pitch";
    this.throwButton.addEventListener("click", () => this.confirm());

    const hint = document.createElement("p");
    hint.className = "pitch-call-hint";
    hint.textContent = "1–4 type · arrows aim · Space throws";

    this.root.replaceChildren(typeGroup, zoneWrap, this.summary, this.throwButton, hint);
    this.syncSelection(false);
  }

  private makeLocationButton(id: string, label: string, className: string): HTMLButtonElement {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = className;
    btn.dataset.target = id;
    btn.setAttribute("role", "radio");
    btn.setAttribute("aria-label", label);
    btn.textContent = shortLabel(label);
    btn.addEventListener("click", () => {
      this.setTarget(id, true);
      btn.focus();
    });
    this.locationButtons.set(id, btn);
    return btn;
  }

  /** Show/hide and enable controls when the human is pitching. */
  setActive(active: boolean): void {
    this.active = active;
    this.root.hidden = !active;
    for (const btn of this.typeButtons.values()) btn.disabled = !active;
    for (const btn of this.locationButtons.values()) btn.disabled = !active;
    this.throwButton.disabled = !active || this.pending === null;
    if (active) this.syncSelection(false);
  }

  beginWaiting(): void {
    this.throwButton.disabled = this.root.hidden;
    if (!this.root.hidden) {
      this.throwButton.focus();
    }
  }

  waitForCall(): Promise<PitchCall> {
    if (this.pending) {
      this.pending.reject(new Error("Pitch call superseded"));
      this.pending = null;
    }
    this.beginWaiting();
    this.announceSummary();
    return new Promise<PitchCall>((resolve, reject) => {
      this.pending = { resolve, reject };
    });
  }

  cancelWait(): void {
    if (!this.pending) {
      this.throwButton.disabled = true;
      return;
    }
    const { reject } = this.pending;
    this.pending = null;
    this.throwButton.disabled = true;
    reject(new Error("Pitch call cancelled"));
  }

  describeCurrent(): string {
    const typeLabel = PITCH_TYPE_OPTIONS.find((o) => o.id === this.type)?.label ?? this.type;
    const target = targetById(this.targetId);
    return describePitchCall(typeLabel, target?.label ?? "the zone");
  }

  private setType(type: PitchType, announce: boolean): void {
    this.type = type;
    this.syncSelection(announce);
  }

  private setTarget(id: string, announce: boolean): void {
    if (!targetById(id)) return;
    this.targetId = id;
    this.syncSelection(announce);
  }

  private syncSelection(announce: boolean): void {
    for (const [type, btn] of this.typeButtons) {
      const on = type === this.type;
      btn.setAttribute("aria-checked", on ? "true" : "false");
      btn.classList.toggle("is-selected", on);
      btn.tabIndex = on ? 0 : -1;
    }
    for (const [id, btn] of this.locationButtons) {
      const on = id === this.targetId;
      btn.setAttribute("aria-checked", on ? "true" : "false");
      btn.classList.toggle("is-selected", on);
      btn.tabIndex = on ? 0 : -1;
    }
    this.summary.textContent = this.describeCurrent();
    if (announce) this.announceSummary();
  }

  private announceSummary(): void {
    // Re-assign to retrigger polite live region when the text is unchanged.
    const text = this.describeCurrent();
    this.summary.textContent = "";
    this.summary.textContent = text;
  }

  private confirm(): void {
    if (!this.pending) return;
    const target = targetById(this.targetId) ?? ZONE_TARGETS[4]!;
    const call: PitchCall = {
      profile: PROFILES[this.type],
      location: { ...target.location },
    };
    savePitchCall({ type: this.type, targetId: target.id });
    const { resolve } = this.pending;
    this.pending = null;
    this.throwButton.disabled = true;
    this.throwButton.blur();
    resolve(call);
  }
}

function shortLabel(label: string): string {
  const map: Record<string, string> = {
    "High and inside": "HI",
    "High middle": "HM",
    "High and away": "HA",
    "Middle inside": "MI",
    "Right down the middle": "Mid",
    "Middle away": "MA",
    "Low and inside": "LI",
    "Low middle": "LM",
    "Low and away": "LA",
    "Chase inside": "In",
    "In the dirt": "Dirt",
    "Chase low and away": "Away",
  };
  return map[label] ?? label.slice(0, 3);
}

function isTextEntry(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName;
  return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || target.isContentEditable;
}
