import type { AudioEngine } from "../AudioEngine.ts";
import type { PitchLocation, PitchProfile, PitchType } from "../../timing/Timeline.ts";
import { locationToCutoff, locationToPan } from "../../timing/Timeline.ts";
import { FIELD_POSITIONS, buildCurve, noiseBurst, spatialPanner } from "./shared.ts";

/**
 * The pitch itself — the one sound the whole game is played off.
 *
 * Unlike every other field voice, the flight does **not** go through an HRTF
 * panner. That is a deliberate trade. HRTF is more realistic, but its perceived
 * lateral position is soft and listener-dependent, and here the horizontal cue is
 * not decoration: it is the information the batter needs to decide whether the
 * pitch is hittable. A StereoPanner is blunter, louder about where it is, and
 * identical on every pair of headphones. Legibility wins over realism.
 *
 * Three cues are encoded, exactly as the brief specifies:
 *
 *   horizontal location -> stereo pan, arriving late so the ball "reveals" itself
 *   vertical location   -> lowpass cutoff; letters are bright, dirt is muffled
 *   pitch type          -> frequency contour of the flight tone
 */

const CURVE_POINTS = 128;

/** Hz over normalised flight time, per pitch type. */
const CONTOURS: Record<PitchType, (t: number) => number> = {
  // Short, hard, relentless rise. Nothing to read but speed.
  fastball: (t) => 340 + 660 * Math.pow(t, 0.55),
  // Climbs like a fastball, then snaps down and sideways in the last third.
  slider: (t) => 360 + 470 * Math.pow(t, 0.6) - (t > 0.68 ? 190 * ((t - 0.68) / 0.32) : 0),
  // The dropping curve from the brief: starts high, falls away, accelerating late.
  curveball: (t) => 640 - 400 * Math.pow(t, 1.8),
  // Delayed and low-register. Sounds like it is arriving until it isn't.
  changeup: (t) => 230 + 140 * Math.pow(t, 2.4),
};

export interface PitchFlightHandles {
  /** Kill the flight tone early — used when the bat gets to the ball. */
  cutAt(time: number): void;
}

export function playPitchFlight(
  engine: AudioEngine,
  profile: PitchProfile,
  location: PitchLocation,
  releaseTime: number,
  plateTime: number,
): PitchFlightHandles {
  const { ctx } = engine;
  const flight = Math.max(plateTime - releaseTime, 0.05);
  const field = engine.busInput("field");

  // --- Release: a hard whoosh from the mound ------------------------------
  const releasePanner = spatialPanner(ctx, FIELD_POSITIONS.mound);
  releasePanner.connect(field);
  // Beat 4 of the pulse the windup laid down. Loud and bright on purpose: this is
  // the last hard reference the batter gets before the ball arrives, and a fastball
  // crosses the plate exactly one beat after it.
  // Crisper and a touch louder than the original — beat 4 has to cut through so
  // the batter can latch the one-beat-to-the-plate interval.
  noiseBurst(engine, releasePanner, {
    at: releaseTime,
    duration: 0.08,
    color: "white",
    frequency: 2900,
    q: 1.05,
    peak: 0.95,
    attack: 0.0012,
  });

  // --- Flight chain --------------------------------------------------------
  const pan = ctx.createStereoPanner();
  pan.connect(field);

  const cutoff = ctx.createBiquadFilter();
  cutoff.type = "lowpass";
  cutoff.Q.value = 1.4;
  cutoff.connect(pan);

  const mix = ctx.createGain();
  mix.connect(cutoff);

  // Tonal core: the pitch-type contour lives here.
  const tone = ctx.createOscillator();
  tone.type = "triangle";
  const toneGain = ctx.createGain();
  toneGain.gain.value = 0.28;
  tone.connect(toneGain);
  toneGain.connect(mix);

  // Seam whir: noise through a resonant bandpass tracking the same contour an
  // octave up. This is what stops the flight from sounding like a test tone.
  const whir = engine.noise.source("white", { loop: true });
  const whirBand = ctx.createBiquadFilter();
  whirBand.type = "bandpass";
  whirBand.Q.value = 6;
  const whirGain = ctx.createGain();
  whirGain.gain.value = 0.5;
  whir.connect(whirBand);
  whirBand.connect(whirGain);
  whirGain.connect(mix);

  const contour = CONTOURS[profile.type];
  const toneCurve = buildCurve(CURVE_POINTS, contour);
  const whirCurve = buildCurve(CURVE_POINTS, (t) => contour(t) * 2.1);
  tone.frequency.setValueCurveAtTime(toneCurve, releaseTime, flight);
  whirBand.frequency.setValueCurveAtTime(whirCurve, releaseTime, flight);

  // Approach: quiet at release, rushing in hard at the end.
  //
  // The exponent here is a gameplay parameter, not a taste one. Too low and the
  // swell is already near full level well before the plate, which smears the
  // perceived moment of arrival across tens of milliseconds — the same order as
  // the entire perfect-contact window. The batter then cannot place the beat even
  // with correct calibration, because there is no sharp beat to place. Steep is
  // also what makes the calibration transfer: that measures against a crisp click,
  // so the pitch needs an equally locatable peak.
  const approach = buildCurve(CURVE_POINTS, (t) => 0.04 + 0.96 * Math.pow(t, 3.2));
  mix.gain.setValueCurveAtTime(approach, releaseTime, flight);

  // Location cues resolve around two-thirds of the way in — early enough for the
  // batter to act on, late enough that he has to actually listen for them.
  const targetPan = locationToPan(location);
  const panCurve = buildCurve(CURVE_POINTS, (t) => targetPan * Math.min(1, Math.pow(t, 1.2) * 1.15));
  pan.pan.setValueCurveAtTime(panCurve, releaseTime, flight);

  const targetCutoff = locationToCutoff(location);
  const cutoffCurve = buildCurve(CURVE_POINTS, (t) => {
    const blend = Math.min(1, Math.pow(t, 1.1) * 1.15);
    return 1500 + (targetCutoff - 1500) * blend;
  });
  cutoff.frequency.setValueCurveAtTime(cutoffCurve, releaseTime, flight);

  // A short tail past the plate so a taken pitch doesn't stop dead in mid-air —
  // but short, because a long one pulls the perceived arrival later than plateTime.
  const naturalEnd = plateTime + 0.035;
  mix.gain.setValueAtTime(1, plateTime);
  mix.gain.exponentialRampToValueAtTime(0.0001, naturalEnd);

  tone.start(releaseTime);
  tone.stop(naturalEnd + 0.05);
  whir.start(releaseTime, engine.noise.randomOffset(flight + 0.2));
  whir.stop(naturalEnd + 0.05);

  let cut = false;
  return {
    cutAt(time: number): void {
      if (cut) return;
      cut = true;
      // Contact interrupts the flight. Cancel the tail, snap the level down over
      // 12 ms — fast enough to be masked by the crack, slow enough not to click.
      const t = Math.max(time, ctx.currentTime);
      mix.gain.cancelScheduledValues(t);
      mix.gain.setValueAtTime(Math.max(mix.gain.value, 0.0002), t);
      mix.gain.exponentialRampToValueAtTime(0.0001, t + 0.012);
      tone.stop(t + 0.02);
      whir.stop(t + 0.02);
    },
  };
}
