import { advanceOnBattedOut, advanceOnHit, advanceOnWalk, type AdvanceNote } from "./Baserunners.ts";
import type { PlayResult } from "./OutcomeResolver.ts";
import type { Player } from "./Player.ts";
import type { Rng } from "./PitchSelector.ts";
import { hitAdvanceSpeedFactor } from "./Ratings.ts";
import type { Team } from "./Teams.ts";

/**
 * GameState — the full nine innings: count, outs, score, bases, and lineups.
 *
 * `applyPlay` is the single entry point. It used to be four separate methods
 * (`applyBall`, `applyStrike`, `applyInPlayOut`, `applyHit`) that the caller had to
 * pre-classify a `PlayResult` into — but baserunner advancement needs the outs
 * count *and* the bases *and* the count together (a double play needs to know outs
 * before deciding whether it can happen at all), so that classification belonged
 * here, not in the composition root.
 */

export type Half = "top" | "bottom";

export interface BaseState {
  first: boolean;
  second: boolean;
  third: boolean;
}

export interface Score {
  home: number;
  away: number;
}

export interface GameSnapshot {
  inning: number;
  half: Half;
  outs: number;
  balls: number;
  strikes: number;
  score: Score;
  bases: BaseState;
  batter: string;
  pitcher: string;
  /** Short name of whoever is at bat / in the field right now. */
  battingTeam: string;
  fieldingTeam: string;
  /**
   * Fixed home/away short names — unlike `battingTeam`/`fieldingTeam`, these don't
   * flip with the half-inning, which is what the scoreboard and any game-over
   * summary need: "who is home" is a constant, "who is batting" isn't.
   */
  homeTeam: string;
  awayTeam: string;
  /** True once the game has ended, by regulation or walk-off. */
  gameOver: boolean;
}

/** What a single pitch did to the plate appearance. */
export type PlateOutcome =
  | { kind: "pitch" }
  | { kind: "walk" }
  | { kind: "strikeout"; swinging: boolean }
  | { kind: "out" }
  | { kind: "hit" };

/**
 * Everything the caller needs to narrate and mix a play, beyond the bare
 * `PlateOutcome`. Kept separate from the snapshot because it describes what
 * *changed* on this specific play, not the state of the game after it.
 */
export interface PlayReport {
  outcome: PlateOutcome;
  runsScored: number;
  /** Outs added to the half-inning by this play (0, 1, or 2 — a double play). */
  outsRecorded: number;
  note: AdvanceNote;
  basesBefore: BaseState;
  basesAfter: BaseState;
  /** True when this play was the third (or fourth, on a double play) out. */
  inningEnded: boolean;
  gameEnded: boolean;
  /** True when the game ended on this exact play because the home team took the lead. */
  walkOff: boolean;
}

const EMPTY_BASES: BaseState = { first: false, second: false, third: false };

/** Nine innings, same as the real thing — extras continue past this. */
const REGULATION_INNINGS = 9;

export class GameState {
  private readonly home: Team;
  private readonly away: Team;
  private readonly rng: Rng;

  private _inning = 1;
  private _half: Half = "top";
  private _outs = 0;
  private _balls = 0;
  private _strikes = 0;
  private _bases: BaseState = EMPTY_BASES;
  private _score: Score = { home: 0, away: 0 };
  private _gameOver = false;

  private awayBatterIndex = 0;
  private homeBatterIndex = 0;

  constructor(home: Team, away: Team, rng: Rng = Math.random) {
    this.home = home;
    this.away = away;
    this.rng = rng;
  }

  snapshot(): GameSnapshot {
    return {
      inning: this._inning,
      half: this._half,
      outs: this._outs,
      balls: this._balls,
      strikes: this._strikes,
      score: { ...this._score },
      bases: { ...this._bases },
      batter: this.currentBatter().name,
      pitcher: this.currentPitcher().name,
      battingTeam: this.battingTeam.shortName,
      fieldingTeam: this.fieldingTeam.shortName,
      homeTeam: this.home.shortName,
      awayTeam: this.away.shortName,
      gameOver: this._gameOver,
    };
  }

  get count(): { balls: number; strikes: number } {
    return { balls: this._balls, strikes: this._strikes };
  }

  get outs(): number {
    return this._outs;
  }

  get gameOver(): boolean {
    return this._gameOver;
  }

  private get battingTeam(): Team {
    return this._half === "top" ? this.away : this.home;
  }

  private get fieldingTeam(): Team {
    return this._half === "top" ? this.home : this.away;
  }

  private get battingIndex(): number {
    return this._half === "top" ? this.awayBatterIndex : this.homeBatterIndex;
  }

  private get battingSide(): "home" | "away" {
    return this._half === "top" ? "away" : "home";
  }

  /** Active hitter for the current half. */
  currentBatter(): Player {
    return this.battingTeam.lineup[this.battingIndex % 9]!;
  }

  /** Active pitcher for the current half. */
  currentPitcher(): Player {
    return this.fieldingTeam.pitcher;
  }

  /**
   * Apply one pitch's result to the game. This is the only way the score, bases,
   * count, or outs change.
   */
  applyPlay(play: PlayResult): PlayReport {
    if (this._gameOver) {
      throw new Error("Cannot apply a play after the game has ended");
    }

    const basesBefore = { ...this._bases };

    switch (play) {
      case "ball":
        this._balls++;
        if (this._balls < 4) return this.midCount(basesBefore);
        return this.resolveWalk(basesBefore);

      case "called-strike":
      case "swinging-strike":
      case "foul-ball": {
        const isFoul = play === "foul-ball";
        if (isFoul && this._strikes >= 2) return this.midCount(basesBefore);
        this._strikes++;
        if (this._strikes < 3) return this.midCount(basesBefore);
        return this.resolveStrikeout(play === "swinging-strike", basesBefore);
      }

      case "home-run":
      case "double":
      case "single": {
        const gained = play === "home-run" ? 4 : play === "double" ? 2 : 1;
        const speed = this.currentBatter().batter?.speed ?? 70;
        const advance = advanceOnHit(this._bases, gained, this.rng, hitAdvanceSpeedFactor(speed));
        return this.resolvePlateAppearance(
          { kind: "hit" },
          advance,
          basesBefore,
          /* recordsOut */ false,
        );
      }

      case "ground-out":
      case "fly-out":
      case "line-out":
      case "pop-up": {
        const advance = advanceOnBattedOut(this._bases, play, this._outs, this.rng);
        return this.resolvePlateAppearance({ kind: "out" }, advance, basesBefore, /* recordsOut */ true);
      }
    }
  }

  private midCount(basesBefore: BaseState): PlayReport {
    return {
      outcome: { kind: "pitch" },
      runsScored: 0,
      outsRecorded: 0,
      note: null,
      basesBefore,
      basesAfter: { ...this._bases },
      inningEnded: false,
      gameEnded: false,
      walkOff: false,
    };
  }

  private resolveWalk(basesBefore: BaseState): PlayReport {
    const advance = advanceOnWalk(this._bases);
    this._bases = advance.bases;
    this._score[this.battingSide] += advance.runsScored;
    const walkOff = this.checkWalkOff(advance.runsScored);
    this.endPlateAppearance();

    return {
      outcome: { kind: "walk" },
      runsScored: advance.runsScored,
      outsRecorded: 0,
      note: null,
      basesBefore,
      basesAfter: { ...this._bases },
      inningEnded: false,
      gameEnded: walkOff,
      walkOff,
    };
  }

  private resolveStrikeout(swinging: boolean, basesBefore: BaseState): PlayReport {
    this.endPlateAppearance();
    const inningEnded = this.recordOuts(1);

    return {
      outcome: { kind: "strikeout", swinging },
      runsScored: 0,
      outsRecorded: 1,
      note: null,
      basesBefore,
      basesAfter: { ...this._bases },
      inningEnded,
      gameEnded: this._gameOver,
      walkOff: false,
    };
  }

  private resolvePlateAppearance(
    outcome: PlateOutcome,
    advance: { bases: BaseState; runsScored: number; extraOuts: number; note: AdvanceNote },
    basesBefore: BaseState,
    recordsOut: boolean,
  ): PlayReport {
    this._bases = advance.bases;
    this._score[this.battingSide] += advance.runsScored;

    // A walk-off is checked before the out bookkeeping below: the go-ahead run on a
    // batted-out sacrifice fly still ends the game the instant it crosses the
    // plate, whether or not the batter himself is out at first.
    const walkOff = this.checkWalkOff(advance.runsScored);
    this.endPlateAppearance();

    const outsThisPlay = recordsOut ? 1 + advance.extraOuts : 0;
    const inningEnded = walkOff ? false : this.recordOuts(outsThisPlay);

    return {
      outcome,
      runsScored: advance.runsScored,
      outsRecorded: outsThisPlay,
      note: advance.note,
      basesBefore,
      basesAfter: { ...this._bases },
      inningEnded,
      gameEnded: this._gameOver,
      walkOff,
    };
  }

  /** True, and ends the game, if this play just put the home team ahead late enough to matter. */
  private checkWalkOff(runsScoredThisPlay: number): boolean {
    if (runsScoredThisPlay <= 0) return false;
    if (this._half !== "bottom" || this._inning < REGULATION_INNINGS) return false;
    if (this._score.home <= this._score.away) return false;
    this._gameOver = true;
    return true;
  }

  /** Resets the count and advances the batting order. Runs on every plate appearance. */
  private endPlateAppearance(): void {
    this._balls = 0;
    this._strikes = 0;
    if (this._half === "top") this.awayBatterIndex++;
    else this.homeBatterIndex++;
  }

  /** Adds outs and rolls the half-inning or ends the game if they reach three. Returns whether the inning ended. */
  private recordOuts(count: number): boolean {
    if (count <= 0) return false;
    this._outs = Math.min(3, this._outs + count);
    if (this._outs < 3) return false;

    this.rolloverHalfInning();
    return true;
  }

  private rolloverHalfInning(): void {
    this._outs = 0;
    this._bases = EMPTY_BASES;

    if (this._half === "top") {
      this._half = "bottom";
      // The home team doesn't need to bat if it's already ahead heading into the
      // last scheduled inning or any extra inning — the game is over the moment
      // the top half ends.
      if (this._inning >= REGULATION_INNINGS && this._score.home > this._score.away) {
        this._gameOver = true;
      }
      return;
    }

    // Bottom half just ended without a walk-off. In or past the last scheduled
    // inning, an unequal score ends the game; a tie sends it to extras.
    if (this._inning >= REGULATION_INNINGS && this._score.home !== this._score.away) {
      this._gameOver = true;
      return;
    }

    this._half = "top";
    this._inning++;
  }

  reset(): void {
    this._inning = 1;
    this._half = "top";
    this._outs = 0;
    this._balls = 0;
    this._strikes = 0;
    this._bases = EMPTY_BASES;
    this._score = { home: 0, away: 0 };
    this._gameOver = false;
    this.awayBatterIndex = 0;
    this.homeBatterIndex = 0;
  }
}

/** Formats the count the way a broadcaster says it: balls first. */
export function formatCount(balls: number, strikes: number): string {
  return `${balls}-${strikes}`;
}

/** "Pirates lead it, 4 to 2" / "tied at 3" — how a broadcaster states the score. */
export function formatScore(score: Score, homeName: string, awayName: string): string {
  if (score.home === score.away) return `tied at ${score.home}`;
  return score.home > score.away
    ? `${homeName} lead it, ${score.home} to ${score.away}`
    : `${awayName} lead it, ${score.away} to ${score.home}`;
}

/** Bare digits, higher score first — the way a scoreboard reads. */
export function formatScoreline(score: Score): string {
  const [hi, lo] = score.home >= score.away ? [score.home, score.away] : [score.away, score.home];
  return `${hi}-${lo}`;
}
