import type { AudioEngine } from "../audio/AudioEngine.ts";
import type { RadioLog } from "../ui/RadioLog.ts";
import { cancelSpeech, speakNow, warmUpSpeech } from "./speech.ts";
import { estimateSpokenSeconds, type Phrase, type SpeakHandle, type VoiceBackend } from "./VoiceBackend.ts";

/**
 * SpeechVoiceBackend — intelligible booth + umpire lines via Web Speech.
 *
 * Trade-off, stated plainly: `speechSynthesis` is not on the Web Audio graph, so
 * it cannot be AM-filtered or hard-panned. In exchange, the listener can understand
 * the words. The radio log still carries every line; crowd ducking still runs on
 * the audio clock; delivery (`action.*`) stays silent so the windup pulse is not
 * talked over.
 */
export class SpeechVoiceBackend implements VoiceBackend {
  private readonly engine: AudioEngine;
  private readonly log: RadioLog;

  constructor(engine: AudioEngine, log: RadioLog) {
    this.engine = engine;
    this.log = log;
    warmUpSpeech();
  }

  estimateDuration(phrase: Phrase): number {
    // Web Speech runs slower than the words-per-second model, and engines vary by
    // OS/voice. Pad generously so the queue does not hand the mic to the next line
    // while the previous utterance is still in the browser TTS queue.
    return estimateSpokenSeconds(phrase.text, phrase.energy) * 1.55 + 0.35;
  }

  speak(phrase: Phrase, atContextTime: number): SpeakHandle {
    const durationSec = this.estimateDuration(phrase);
    const speakAloud = shouldSpeakAloud(phrase);

    if (phrase.speaker !== "umpire" && speakAloud) {
      this.engine.duckFor(atContextTime, durationSec);
    }

    const perfTarget = this.engine.clock.audioToPerf(atContextTime);
    const delayMs = Math.max(0, perfTarget - performance.now());

    let cancelled = false;
    let speechToken = -1;

    const timer = setTimeout(() => {
      if (cancelled) return;
      this.log.append(phrase);
      if (!speakAloud) return;
      // Enqueue — do not cancel. Truncation was happening because speakNow used to
      // hard-stop the previous sentence whenever the next timer fired a bit early.
      speechToken = speakNow({
        text: phrase.text,
        speaker: phrase.speaker,
        energy: phrase.energy,
        interrupt: false,
      });
    }, delayMs);

    return {
      durationSec,
      cancel: () => {
        cancelled = true;
        clearTimeout(timer);
        cancelSpeech(speechToken);
      },
    };
  }
}

/**
 * Delivery calls fire as the windup starts. Speaking them aloud buries the thud
 * pulse the batter times off — log them, don't say them.
 */
function shouldSpeakAloud(phrase: Phrase): boolean {
  return !phrase.id.startsWith("action.");
}
