/**
 * Difficulty — how hard the pitcher is, and how much the mix teaches the beat.
 *
 * Timing clarity is audio-first: blind players must be able to learn the swing
 * without the Gameday board. Visual beat strip settings mirror the same coach;
 * they are never required to time a pitch.
 */

export type DifficultyId = "rookie" | "pro" | "all-star" | "legend";

export interface DifficultyConfig {
  readonly id: DifficultyId;
  readonly label: string;
  /** Short line announced when the preset changes (screen-reader + spoken). */
  readonly announce: string;
  readonly perfectWindowMs: number;
  readonly contactWindowMs: number;
  /**
   * Pitch mix:
   *   fastball — Rookie practice (pulse only)
   *   fb-heavy — mostly fastballs, some offspeed
   *   full — current arsenal behaviour
   */
  readonly pitchMix: "fastball" | "fb-heavy" | "full";
  /** How far off the plate the pitcher hunts (fed into PitchSelector aggression). */
  readonly locationAggression: number;
  /** Rising/countable beat tones on windup beats 1–3. */
  readonly countableBeats: boolean;
  /** Short field-bus click at plate time. */
  readonly plateTick: boolean;
  /** Spoken "swing" on beat 5 (Rookie learning cue). */
  readonly spokenSwing: boolean;
  /** Sight beat strip for sighted players. */
  readonly visualCoach: boolean;
  /** Flash SWING on beat 5 in the visual strip. */
  readonly visualSwingFlash: boolean;
}

