export const DEFAULT_DIFFICULTY: DifficultyId = "rookie";
export const DIFFICULTY_ORDER: readonly DifficultyId[] = ["rookie", "pro", "all-star", "legend"];

const STORAGE_KEY = "botn.difficulty";

export function isDifficultyId(value: string): value is DifficultyId {
  return value in DIFFICULTIES;
}

export function loadDifficultyId(): DifficultyId {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw && isDifficultyId(raw)) return raw;
  } catch {
    // private mode / no storage — fall through
  }
  return DEFAULT_DIFFICULTY;
}

export function saveDifficultyId(id: DifficultyId): void {
  try {
    localStorage.setItem(STORAGE_KEY, id);
  } catch {
    // ignore
  }
}

export function getDifficulty(id: DifficultyId = loadDifficultyId()): DifficultyConfig {
  return DIFFICULTIES[id];
}
