import type { Phrase } from "../commentary/VoiceBackend.ts";

/**
 * RadioLog — the broadcast, rendered.
 *
 * The readable half of the broadcast. The synth (or a future sampled) backend
 * plays the cadence; this carries the words. It is an ARIA live region, so a
 * screen reader announces each line as it arrives — which for a game with no
 * graphics is not an accessibility afterthought, it is a second, entirely usable
 * way to play.
 */

const MAX_LINES = 120;

const SPEAKER_LABEL: Record<Phrase["speaker"], string> = {
  announcer: "PxP",
  color: "Color",
  umpire: "Ump",
};

export class RadioLog {
  private readonly list: HTMLOListElement;

  constructor(list: HTMLOListElement) {
    this.list = list;
  }

  append(phrase: Phrase): void {
    const item = document.createElement("li");
    item.className = `log-line log-line--${phrase.speaker}`;

    const speaker = document.createElement("span");
    speaker.className = "log-speaker";
    speaker.textContent = SPEAKER_LABEL[phrase.speaker];

    const text = document.createElement("span");
    text.className = "log-text";
    text.textContent = phrase.text;

    item.append(speaker, text);
    this.list.append(item);

    while (this.list.childElementCount > MAX_LINES) {
      this.list.firstElementChild?.remove();
    }

    // Only follow the feed if the listener hasn't scrolled back to read something.
    const nearBottom = this.list.scrollHeight - this.list.scrollTop - this.list.clientHeight < 80;
    if (nearBottom) this.list.scrollTop = this.list.scrollHeight;
  }

  clear(): void {
    this.list.replaceChildren();
  }
}
